// Interview is scored across 4 dimensions (dress/appearance, communication,
// experience proven, creativity), each 1-5 — averaged and scaled to 0-100.
// Returns null if none of the 4 have been scored yet.
function interviewOverallScore(a){var parts=[a.interview_dress_score,a.interview_communication_score,a.interview_experience_score,a.interview_creativity_score].filter(function(v){return v!=null;});if(!parts.length)return null;return Math.round(parts.reduce(function(s,v){return s+v;},0)/parts.length*20);}// Combines the AI CV score, a manually-entered portfolio score, and the
// post-interview 4-dimension score into one overall application score —
// a candidate only ever CV-scored shouldn't be ranked against one who's
// also been interviewed/portfolio-reviewed using just the raw AI number.
// Averages whichever of the 3 components are actually present, so a
// candidate missing the later stages still ranks fairly on what exists.
function computeApplicationScore(a){var interview=interviewOverallScore(a);var parts=[a.ai_score,a.portfolio_score,interview].filter(function(v){return v!=null;});if(!parts.length)return null;return Math.round(parts.reduce(function(s,v){return s+v;},0)/parts.length);}function applicationRank(a){var score=computeApplicationScore(a);return score!==null&&score!==void 0?score:-1;}// Same "what's missing" rules imap-recruitment-cron.php uses when deciding
// whether to send a "complete your application" email — kept in sync so
// the manual "Send Complete Your Application" button in ApplicationDetail
// and the public CompleteApplicationPage form always agree on what still
// needs filling in.
// api.php's castRow() auto-decodes any TEXT column whose value looks like
// JSON (starts with [ or {) into a real array/object before the response
// ever reaches the browser — so a field can arrive either as a raw JSON
// string OR as already-decoded data depending on what's stored. Calling
// JSON.parse() on an already-decoded array/object throws (it gets
// coerced to a string first), so any array-shaped field from the API
// needs this instead of a plain JSON.parse.
// A "slot" value is only ever a real date when it came from one of the
// proposed options — a candidate-suggested alternative (free text like
// "any weekday after 3pm") isn't parseable at all, and new Date() on it
// doesn't throw, it just silently produces the string "Invalid Date"
// which then looks like a real (broken) value instead of the original text.
function fmtDateOrText(v){if(!v)return"";var d=new Date(v);return isNaN(d.getTime())?v:fmtDateTime(v);}function parseMaybeJson(v,fallback){if(v==null)return fallback;if(typeof v!=="string")return v;try{return JSON.parse(v);}catch(e){return fallback;}}// Contact report attendees are always displayed client side first, then
